if (!defined('CLI_SCRIPT')) { define('CLI_SCRIPT', true); }
require('/www/moodle/config.php');
require_once($CFG->dirroot . '/lib/questionlib.php');
require_once($CFG->dirroot . '/question/format/xml/format.php');
try {
    $course = $DB->get_record('course', ['shortname' => 'GUESSIT01'], '*', MUST_EXIST);
    $coursecontext = context_course::instance($course->id);
    $category = question_make_default_categories([$coursecontext]);
    $xml = <<<'GUESSITXML'
<?xml version="1.0" encoding="UTF-8"?>
<quiz>
<!-- question: 835  -->
  <question type="guessit">
    <name>
      <text>Guessit001</text>
    </name>
    <questiontext format="html">
      <text><![CDATA[<p>Guess an English proverb</p>]]></text>
    </questiontext>
    <generalfeedback format="html">
      <text></text>
    </generalfeedback>
    <defaultgrade>6</defaultgrade>
    <penalty>0</penalty>
    <hidden>0</hidden>
    <idnumber></idnumber>
    <guessitgaps>Too many cooks spoil the broth.</guessitgaps>
    <nbtriesbeforehelp>6</nbtriesbeforehelp>
    <nbmaxtrieswordle>0</nbmaxtrieswordle>
    <wordle>0</wordle>
    <answer fraction="100" format="moodle_auto_format">
      <text>Too</text>
      <feedback format="moodle_auto_format">
        <text></text>
      </feedback>
    </answer>
    <answer fraction="100" format="moodle_auto_format">
      <text>many</text>
      <feedback format="moodle_auto_format">
        <text></text>
      </feedback>
    </answer>
    <answer fraction="100" format="moodle_auto_format">
      <text>cooks</text>
      <feedback format="moodle_auto_format">
        <text></text>
      </feedback>
    </answer>
    <answer fraction="100" format="moodle_auto_format">
      <text>spoil</text>
      <feedback format="moodle_auto_format">
        <text></text>
      </feedback>
    </answer>
    <answer fraction="100" format="moodle_auto_format">
      <text>the</text>
      <feedback format="moodle_auto_format">
        <text></text>
      </feedback>
    </answer>
    <answer fraction="100" format="moodle_auto_format">
      <text>broth.</text>
      <feedback format="moodle_auto_format">
        <text></text>
      </feedback>
    </answer>
    <guessitgaps>Too many cooks spoil the broth.</guessitgaps>
    <nbtriesbeforehelp>6</nbtriesbeforehelp>
    <nbmaxtrieswordle>0</nbmaxtrieswordle>
    <wordle>0</wordle>
    <!-- guessit release:1.0 version:2025012101 Moodle version:2024100701.04 release:4.5.1+ (Build: 20250103) -->
  </question>

</quiz>
GUESSITXML;
    $tmpdir = make_request_directory();
    $tmpfile = $tmpdir . '/guessit.xml';
    file_put_contents($tmpfile, $xml);
    $qformat = new qformat_xml();
    $qformat->setCategory($category);
    $qformat->setContexts([$coursecontext]);
    $qformat->setCourse($course);
    $qformat->setFilename($tmpfile);
    $qformat->setMatchgrades('error');
    $qformat->setCatfromfile(false);
    $qformat->setContextfromfile(false);
    $qformat->setStoponerror(false);
    if ($qformat->importpreprocess() && $qformat->importprocess() && $qformat->importpostprocess()) {
        echo "Imported sample guessit question into category id={$category->id} (courseid={$course->id})\n";
    } else {
        echo "Import returned false\n";
    }
} catch (\Throwable $e) {
    echo 'ERROR: ' . $e->getMessage() . "\n";
}
